from PIL import Image, ImageDraw
img = Image.open('radiograph.jpg').convert('L')
tiles = [
 ('G1_U_R1', 480,300,1000,680), ('G2_U_M', 1000,300,1520,680),
 ('G3_U_L1', 1520,300,2040,680), ('G4_U_L2', 2040,300,2473,680),
 ('G5_L_R1', 400,700,900,1150), ('G6_L_M', 900,700,1400,1150),
 ('G7_L_L1', 1400,700,1900,1150), ('G8_L_L2', 1900,700,2400,1150),
]
for name,x1,y1,x2,y2 in tiles:
    c = img.crop((x1,y1,x2,y2)).resize(((x2-x1)*2,(y2-y1)*2), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for x in range(x1,x2+1,50):
        xx=(x-x1)*2; d.line([(xx,0),(xx,c.height)], fill=170, width=1)
        if (x-x1)%100==0: d.text((xx+2,2), str(x), fill=255)
    for y in range(y1,y2+1,50):
        yy=(y-y1)*2; d.line([(0,yy),(c.width,yy)], fill=170, width=1)
        if (y-y1)%100==0: d.text((2,yy+2), str(y), fill=255)
    c.save(f'crops/{name}.png')
print('ok')
EOF", "description": "Create 8 gridded tiles covering dental arches"}
